class Solution {
public:
    long long maxTaxiEarnings(int n, vector<vector<int>>& rides) {
        vector<vector<pair<int, int>>> rides_by_end(n + 1);
        for (const auto& r : rides) {
            rides_by_end[r[1]].push_back({r[0], r[1] - r[0] + r[2]});
        }
        vector<long long> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            dp[i] = dp[i - 1];
            for (const auto& [s, gain] : rides_by_end[i]) {
                dp[i] = max(dp[i], dp[s] + gain);
            }
        }
        return dp[n];
    }
};

class Solution {
    public long maxTaxiEarnings(int n, int[][] rides) {
        List<List<int[]>> ridesByEnd = new ArrayList<>();
        for (int i = 0; i <= n; i++) ridesByEnd.add(new ArrayList<>());
        for (int[] r : rides) {
            ridesByEnd.get(r[1]).add(new int[]{r[0], r[1] - r[0] + r[2]});
        }
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            for (int[] r : ridesByEnd.get(i)) {
                dp[i] = Math.max(dp[i], dp[r[0]] + r[1]);
            }
        }
        return dp[n];
    }
}

var maxTaxiEarnings = function(n, rides) {
  const ridesByEnd = Array.from({ length: n + 1 }, () => []);
  for (const [s, e, t] of rides) {
    ridesByEnd[e].push([s, e - s + t]);
  }
  const dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    dp[i] = dp[i - 1];
    for (const [s, gain] of ridesByEnd[i]) {
      if (dp[s] + gain > dp[i]) dp[i] = dp[s] + gain;
    }
  }
  return dp[n];
};
